def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    if not (0 <= start[0] < rows and 0 <= start[1] < cols or
            0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    visited = set()
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(r, c, path):
        if (r, c) == goal:
            return path + [goal]
        if (r, c) in visited or grid[r][c] == '#':
            return None
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result = dfs(nr, nc, path + [(r, c)])
                if result:
                    return result
        return None

    result = dfs(start[0], start[1], [])
    return result if result else []
